  {suggestions.length>0&&<div className="ingredient-autocomplete-list" role="listbox">{suggestions.map((entry,index)=><button type="button" role="option" aria-selected={index===active} className={index===active?"ingredient-autocomplete-option active":"ingredient-autocomplete-option"} key={entry.id} onMouseDown={e=>e.preventDefault()} onMouseEnter={()=>setActive(index)} onClick={()=>{onSelect(entry);setOpen(false)}}><span>{entry.name}</span><small>{entry.estimated===false?"Your saved values / 100 g":`~${entry.kcal} kcal / 100 g · estimate`}</small></button>)}</div>}
  {exact&&<small className="ingredient-match-status found">In ingredient database · nutrition per 100 g</small>}
  {unmatched&&<small className="ingredient-match-status missing">{suggestions.length?"Possible matches above — select one, or save this as a new ingredient.":"Not in ingredient database — enter nutrition per 100 g to add it."}</small>}
